export type IconName = keyof typeof PATHS;

/**
 * Inline SVG icon. Duotone layers use `currentColor` (the secondary layer at
 * 50% opacity), so the icon follows the surrounding text colour.
 */
export function Icon({
  name,
  size = 18,
  className,
  title,
}: {
  name: IconName;
  size?: number;
  className?: string;
  title?: string;
}) {
  return (
    <svg
      className={className ? `icon ${className}` : "icon"}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden={title ? undefined : true}
      role={title ? "img" : undefined}
      dangerouslySetInnerHTML={{ __html: (title ? `<title>${title}</title>` : "") + PATHS[name] }}
    />
  );
}
